"""Hash-bound replay of the three frozen arithmetic heat components."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
import sys


PACKAGE = Path(__file__).resolve().parent
ROOT = PACKAGE.parents[1]
MANIFEST = PACKAGE / 'package_manifest.json'


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def local_path(relative: str) -> Path:
    path = (ROOT / relative).resolve()
    if not path.is_relative_to(ROOT):
        raise AssertionError(f'Inventory path escapes package root: {relative}')
    return path


def computation_bytes(path: Path, start: str, end: str) -> bytes:
    data = path.read_bytes()
    left, right = start.encode(), end.encode()
    if data.count(left) != 1 or data.count(right) != 1:
        raise AssertionError(f'Ambiguous computation delimiters: {path.name}')
    first, last = data.index(left), data.index(right)
    if last <= first:
        raise AssertionError(f'Invalid computation interval: {path.name}')
    return data[first:last]


def check_passed(item: dict) -> bool:
    if 'passed' in item:
        return item['passed'] is True
    return item.get('status') == 'exact_zero_residual'


def verify_inventory() -> dict:
    if sys.flags.optimize:
        raise RuntimeError('Optimized Python is unsupported: original exact computations use assertions.')
    manifest = json.loads(MANIFEST.read_text(encoding='utf-8'))
    if manifest['schema'] != 'arithmetic-heat-portable-package-v1':
        raise AssertionError('Unexpected arithmetic heat package schema')
    for relative, expected in manifest['files_sha256'].items():
        if sha256(local_path(relative)) != expected:
            raise AssertionError(f'Included file SHA-256 mismatch: {relative}')
    for replay in manifest['replay_adaptations']:
        original = computation_bytes(local_path(replay['original']), **replay['block_delimiters']['original'])
        portable = computation_bytes(local_path(replay['portable']), **replay['block_delimiters']['portable'])
        if original != portable or hashlib.sha256(original).hexdigest() != replay['block_sha256']:
            raise AssertionError(f'Mathematical computation bytes changed: {replay["portable"]}')
    for proof in manifest['source_proof_snapshot']:
        if sha256(local_path(proof['parent_copy'])) != proof['source_sha256']:
            raise AssertionError(f'Frozen proof differs from source snapshot: {proof["parent_copy"]}')
    return {
        'package_manifest_sha256': sha256(MANIFEST),
        'included_input_files_verified': len(manifest['files_sha256']),
        'proof_files_sha256': {p['parent_copy']: p['source_sha256'] for p in manifest['source_proof_snapshot']},
        'computation_blocks_byte_preserved': True,
        'source_snapshot_receipt_sha256': sha256(PACKAGE / 'provenance' / 'source_snapshot.json'),
        'source_project_required': False,
        'external_source_pdfs_included': False,
    }


def start_replay(script: str) -> tuple[dict, Path]:
    context = verify_inventory()
    context['portable_script_sha256'] = sha256(Path(script))
    output = ROOT / 'checks' / 'arithmetic_heat'
    output.mkdir(parents=True, exist_ok=True)
    return context, output

